<?php require_once __DIR__.'/include/config.php';require_once __DIR__.'/../include/clinical.php';hms_start_session();hms_require_role('admin');$ready=hms_stage6_ready($con);$error='';if($ready&&$_SERVER['REQUEST_METHOD']==='POST'){hms_verify_csrf();try{$id=(int)($_POST['request_id']??0);$status=(string)($_POST['status']??'');if(!$id||!in_array($status,['requested','in_progress','completed','cancelled'],true))throw new InvalidArgumentException('Choose a valid laboratory request and status.');$existing=hms_db_query($con,'SELECT id,result_value FROM laboratory_results WHERE laboratory_request_id=?',[$id])->fetch_assoc();$value=hms_post_string('result_value',4000);$units=hms_post_string('units',80);$range=hms_post_string('reference_range',255);$remarks=hms_post_string('remarks',1000);if($status==='completed'&&$value==='')throw new InvalidArgumentException('A completed request needs a result.');$con->begin_transaction();hms_db_query($con,'UPDATE laboratory_requests SET status=? WHERE id=?',[$status,$id]);if($value!==''||$existing){if($existing){hms_db_query($con,'UPDATE laboratory_results SET result_value=?,units=?,reference_range=?,remarks=?,completed_at=IF(?=\'completed\',NOW(),completed_at),completed_by_admin_id=?,revised_at=NOW() WHERE id=?',[$value?:null,$units?:null,$range?:null,$remarks?:null,$status,(int)$_SESSION['id'],(int)$existing['id']]);hms_db_query($con,'INSERT INTO laboratory_result_audit(laboratory_result_id,admin_id,action,previous_result,new_result) VALUES(?,?,?,?,?)',[(int)$existing['id'],(int)$_SESSION['id'],'revised',$existing['result_value'],$value?:null]);}else{hms_db_query($con,'INSERT INTO laboratory_results(laboratory_request_id,result_value,units,reference_range,remarks,completed_at,completed_by_admin_id) VALUES(?,?,?,?,?,IF(?=\'completed\',NOW(),NULL),?)',[$id,$value?:null,$units?:null,$range?:null,$remarks?:null,$status,(int)$_SESSION['id']]);$rid=(int)$con->insert_id;hms_db_query($con,'INSERT INTO laboratory_result_audit(laboratory_result_id,admin_id,action,new_result) VALUES(?,?,?,?)',[$rid,(int)$_SESSION['id'],'entered',$value?:null]);}}$con->commit();header('Location:laboratory.php?saved=1');exit;}catch(Throwable $e){if($con->errno)$con->rollback();error_log('HMS lab update: '.$e->getMessage());$error=$e instanceof InvalidArgumentException?$e->getMessage():'Laboratory request could not be updated.';}}$rows=$ready?hms_db_query($con,'SELECT l.id,l.test_name,l.status,l.requested_at,u.fullName patient,d.doctorName,r.result_value,r.units,r.reference_range,r.remarks FROM laboratory_requests l JOIN users u ON u.id=l.patient_user_id JOIN doctors d ON d.id=l.doctor_id LEFT JOIN laboratory_results r ON r.laboratory_request_id=l.id ORDER BY l.id DESC'):null;?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Laboratory · MedTech</title><link rel="stylesheet" href="vendor/bootstrap/css/bootstrap.min.css"></head><body><div id="app"><?php include 'include/sidebar.php';?><div class="app-content"><?php include 'include/header.php';?><main class="container"><h1>Laboratory management</h1><?php if(!$ready):?><div class="alert alert-warning"><?=hms_h(hms_clinical_notice())?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=hms_h($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="alert alert-success">Laboratory request updated and audit entry recorded.</div><?php endif;?><?php if($rows)while($r=$rows->fetch_assoc()):?><section class="panel panel-default"><div class="panel-heading"><b><?=hms_h($r['test_name'])?></b> · <?=hms_h($r['patient'])?> · <?=hms_h($r['doctorName'])?> · <?=hms_h(ucfirst($r['status']))?></div><div class="panel-body"><form method="post" class="row"><?=hms_csrf_field()?><input type="hidden" name="request_id" value="<?=hms_h($r['id'])?>"><div class="col-md-2"><select name="status" class="form-control"><option value="requested">Requested</option><option value="in_progress">In progress</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></div><div class="col-md-3"><input class="form-control" name="result_value" value="<?=hms_h($r['result_value'])?>" placeholder="Result"></div><div class="col-md-2"><input class="form-control" name="units" value="<?=hms_h($r['units'])?>" placeholder="Units"></div><div class="col-md-2"><input class="form-control" name="reference_range" value="<?=hms_h($r['reference_range'])?>" placeholder="Reference range"></div><div class="col-md-2"><input class="form-control" name="remarks" value="<?=hms_h($r['remarks'])?>" placeholder="Remarks"></div><div class="col-md-1"><button class="btn btn-primary">Save</button></div></form></div></section><?php endwhile;?></main></div></div></body></html>
